/** The URN of this domain. Each result of check and runOperation names it. */
export const DOMAIN = "urn:urn-forge:toolchain";

/** Each definition: its URN, its base type, the parts of a list or an object, and the names of its own rules. */
export const Definitions = {
  definition_name: { urn: "urn:urn-forge:toolchain:definition:definition_name", base: "string", rules: ["pattern"] },
  type_name: { urn: "urn:urn-forge:toolchain:definition:type_name", base: "string", rules: ["pattern"] },
  naming_request: { urn: "urn:urn-forge:toolchain:definition:naming_request", base: "object", properties: ["definition_name"], rules: ["required"] },
  named_type: { urn: "urn:urn-forge:toolchain:definition:named_type", base: "object", properties: ["type_name"], rules: ["required"] },
  version: { urn: "urn:urn-forge:toolchain:definition:version", base: "string", rules: ["pattern"] },
  from_version: { urn: "urn:urn-forge:toolchain:definition:from_version", base: "string", rules: [] },
  to_version: { urn: "urn:urn-forge:toolchain:definition:to_version", base: "string", rules: [] },
  reason: { urn: "urn:urn-forge:toolchain:definition:reason", base: "string", rules: ["minLength"] },
  version_change: { urn: "urn:urn-forge:toolchain:definition:version_change", base: "object", properties: ["from_version","to_version"], rules: ["required"] },
  breaking_allowed: { urn: "urn:urn-forge:toolchain:definition:breaking_allowed", base: "object", properties: ["reason"], rules: ["required"] },
  breaking_refused: { urn: "urn:urn-forge:toolchain:definition:breaking_refused", base: "object", properties: ["reason"], rules: ["required"] },
  namespace_name: { urn: "urn:urn-forge:toolchain:definition:namespace_name", base: "string", rules: ["pattern"] },
  domain_name: { urn: "urn:urn-forge:toolchain:definition:domain_name", base: "string", rules: ["pattern"] },
  part_kind: { urn: "urn:urn-forge:toolchain:definition:part_kind", base: "string", rules: ["enum"] },
  part_name: { urn: "urn:urn-forge:toolchain:definition:part_name", base: "string", rules: ["pattern"] },
  urn: { urn: "urn:urn-forge:toolchain:definition:urn", base: "string", rules: [] },
  part: { urn: "urn:urn-forge:toolchain:definition:part", base: "object", properties: ["namespace_name","domain_name","part_kind","part_name"], rules: ["required"] },
  part_urn: { urn: "urn:urn-forge:toolchain:definition:part_urn", base: "object", properties: ["urn"], rules: ["required"] },
  candidate: { urn: "urn:urn-forge:toolchain:definition:candidate", base: "string", rules: ["minLength"] },
  namespace_candidate: { urn: "urn:urn-forge:toolchain:definition:namespace_candidate", base: "object", properties: ["candidate"], rules: ["required"] },
  namespace_accepted: { urn: "urn:urn-forge:toolchain:definition:namespace_accepted", base: "object", properties: ["candidate"], rules: ["required"] },
  namespace_refused: { urn: "urn:urn-forge:toolchain:definition:namespace_refused", base: "object", properties: ["candidate"], rules: ["required"] },
  bound_rule: { urn: "urn:urn-forge:toolchain:definition:bound_rule", base: "string", rules: ["enum"] },
  old_bound: { urn: "urn:urn-forge:toolchain:definition:old_bound", base: "number", rules: [] },
  new_bound: { urn: "urn:urn-forge:toolchain:definition:new_bound", base: "number", rules: [] },
  bound_change: { urn: "urn:urn-forge:toolchain:definition:bound_change", base: "object", properties: ["bound_rule","old_bound","new_bound"], rules: ["required"] },
  direction: { urn: "urn:urn-forge:toolchain:definition:direction", base: "string", rules: ["enum"] },
  bound_judged: { urn: "urn:urn-forge:toolchain:definition:bound_judged", base: "object", properties: ["direction"], rules: ["required"] },
} as const;

/** The name of a definition. */
export type DefinitionName = keyof typeof Definitions;

const CHECKS: Readonly<Record<DefinitionName, (value: unknown, path: string, failures: Failure[]) => boolean>> = {
  definition_name: check_definition_name,
  type_name: check_type_name,
  naming_request: check_naming_request,
  named_type: check_named_type,
  version: check_version,
  from_version: check_from_version,
  to_version: check_to_version,
  reason: check_reason,
  version_change: check_version_change,
  breaking_allowed: check_breaking_allowed,
  breaking_refused: check_breaking_refused,
  namespace_name: check_namespace_name,
  domain_name: check_domain_name,
  part_kind: check_part_kind,
  part_name: check_part_name,
  urn: check_urn,
  part: check_part,
  part_urn: check_part_urn,
  candidate: check_candidate,
  namespace_candidate: check_namespace_candidate,
  namespace_accepted: check_namespace_accepted,
  namespace_refused: check_namespace_refused,
  bound_rule: check_bound_rule,
  old_bound: check_old_bound,
  new_bound: check_new_bound,
  bound_change: check_bound_change,
  direction: check_direction,
  bound_judged: check_bound_judged,
};

/** The result of a check: the value, or the rules it breaks. */
export type CheckResult<T> = { readonly ok: true; readonly domain: typeof DOMAIN; readonly value: T } | { readonly ok: false; readonly domain: typeof DOMAIN; readonly failures: readonly Failure[] };

/** The types of the definitions, by name. */
export interface DefinitionTypes {
  readonly definition_name: DefinitionNameValue;
  readonly type_name: TypeName;
  readonly naming_request: NamingRequest;
  readonly named_type: NamedType;
  readonly version: Version;
  readonly from_version: FromVersion;
  readonly to_version: ToVersion;
  readonly reason: Reason;
  readonly version_change: VersionChange;
  readonly breaking_allowed: BreakingAllowed;
  readonly breaking_refused: BreakingRefused;
  readonly namespace_name: NamespaceName;
  readonly domain_name: DomainName;
  readonly part_kind: PartKind;
  readonly part_name: PartName;
  readonly urn: Urn;
  readonly part: Part;
  readonly part_urn: PartUrn;
  readonly candidate: Candidate;
  readonly namespace_candidate: NamespaceCandidate;
  readonly namespace_accepted: NamespaceAccepted;
  readonly namespace_refused: NamespaceRefused;
  readonly bound_rule: BoundRule;
  readonly old_bound: OldBound;
  readonly new_bound: NewBound;
  readonly bound_change: BoundChange;
  readonly direction: Direction;
  readonly bound_judged: BoundJudged;
}

/** Checks a value against a definition: its structure, then each rule. */
export function check<D extends DefinitionName>(definition: D, value: unknown): CheckResult<DefinitionTypes[D]> {
  const failures: Failure[] = [];
  return CHECKS[definition](value, '', failures) ? { ok: true, domain: DOMAIN, value: value as DefinitionTypes[D] } : { ok: false, domain: DOMAIN, failures };
}

/** What an operation answers: one of its outputs, by name, and its value. */
export interface Answer<O extends string, V> {
  readonly output: O;
  readonly value: V;
}

/** An answer of the core: answer('booking', booking). */
export function answer<O extends string, V>(output: O, value: V): Answer<O, V> {
  return { output, value };
}

/** The answers of to_type_name. */
export type ToTypeNameAnswer = Answer<"named_type", NamedType>;

/** The answers of judge_version_change. */
export type JudgeVersionChangeAnswer = Answer<"breaking_allowed", BreakingAllowed> | Answer<"breaking_refused", BreakingRefused>;

/** The answers of name_part. */
export type NamePartAnswer = Answer<"part_urn", PartUrn>;

/** The answers of check_namespace. */
export type CheckNamespaceAnswer = Answer<"namespace_accepted", NamespaceAccepted> | Answer<"namespace_refused", NamespaceRefused>;

/** The answers of judge_weaker_contract. */
export type JudgeWeakerContractAnswer = Answer<"breaking_allowed", BreakingAllowed> | Answer<"breaking_refused", BreakingRefused>;

/** The answers of judge_bound_change. */
export type JudgeBoundChangeAnswer = Answer<"bound_judged", BoundJudged>;

/** The core: a function for each operation, from its input to one of its answers. */
export interface DomainCore {
  /** Name the TypeScript type of a definition, as the generated file does */
  readonly to_type_name: (input: NamingRequest) => ToTypeNameAnswer;
  /** Whether the versions of two manifests allow a breaking change, as diff judges it by semver */
  readonly judge_version_change: (input: VersionChange) => JudgeVersionChangeAnswer;
  /** The URN of a part, as the generated file, diff and gate 5 give it */
  readonly name_part: (input: Part) => NamePartAnswer;
  /** Whether a text is a URN namespace, as the manifest takes it */
  readonly check_namespace: (input: NamespaceCandidate) => CheckNamespaceAnswer;
  /** Whether the versions of two manifests allow a weaker contract, as gate 5 judges it */
  readonly judge_weaker_contract: (input: VersionChange) => JudgeWeakerContractAnswer;
  /** Whether a new bound of a standard rule accepts fewer values or more, as diff and gate 5 judge it */
  readonly judge_bound_change: (input: BoundChange) => JudgeBoundChangeAnswer;
}

/** Each operation: its URN, its input, and its outputs. */
export const Operations = {
  to_type_name: { urn: "urn:urn-forge:toolchain:operation:to_type_name", input: "naming_request", outputs: ["named_type"] },
  judge_version_change: { urn: "urn:urn-forge:toolchain:operation:judge_version_change", input: "version_change", outputs: ["breaking_allowed","breaking_refused"] },
  name_part: { urn: "urn:urn-forge:toolchain:operation:name_part", input: "part", outputs: ["part_urn"] },
  check_namespace: { urn: "urn:urn-forge:toolchain:operation:check_namespace", input: "namespace_candidate", outputs: ["namespace_accepted","namespace_refused"] },
  judge_weaker_contract: { urn: "urn:urn-forge:toolchain:operation:judge_weaker_contract", input: "version_change", outputs: ["breaking_allowed","breaking_refused"] },
  judge_bound_change: { urn: "urn:urn-forge:toolchain:operation:judge_bound_change", input: "bound_change", outputs: ["bound_judged"] },
} as const;

/** The name of an operation. */
export type OperationName = keyof typeof Operations;

const OPERATION_RULES: Readonly<Record<OperationName, (input: any, output: string, value: any, failures: Failure[]) => boolean>> = {
  to_type_name: (input, output, value, failures) => {
    let ok = true;
    switch (output) {
      case "named_type":
        if (!$holds(() => (($size((value as any)["type_name"]) as any) <= ((($size((input as any)["definition_name"]) as any) + (5 as any)) as any)))) {
          failures.push({ definition: "to_type_name", rule: "at_most_the_name_and_value", path: '', failure_message: "The type name is longer than the definition name and Value" });
          ok = false;
        }
        break;
    }
    return ok;
  },
  judge_version_change: (input, output, value, failures) => {
    let ok = true;
    switch (output) {
      case "breaking_refused":
        if (!$holds(() => ((!$matches((input as any)["to_version"], "^0\\.")) && (!$matches((input as any)["to_version"], "^[0-9]+\\.[0-9]+\\.[0-9]+-"))))) {
          failures.push({ definition: "judge_version_change", rule: "stable_and_final", path: '', failure_message: "A 0.x version or a pre-release allows a breaking change" });
          ok = false;
        }
        break;
    }
    return ok;
  },
  name_part: (input, output, value, failures) => {
    let ok = true;
    switch (output) {
      case "part_urn":
        if (!$holds(() => $eq((value as any)["urn"], (((((((((((((("urn:" as any) + ((input as any)["namespace_name"] as any)) as any) + (":" as any)) as any) + ((input as any)["domain_name"] as any)) as any) + (":" as any)) as any) + ((input as any)["part_kind"] as any)) as any) + (":" as any)) as any) + ((input as any)["part_name"] as any))))) {
          failures.push({ definition: "name_part", rule: "joins_the_parts", path: '', failure_message: "The URN is not urn:<namespace>:<domain>:<section>:<name>" });
          ok = false;
        }
        break;
    }
    return ok;
  },
  check_namespace: (input, output, value, failures) => {
    let ok = true;
    switch (output) {
      case "namespace_accepted":
        if (!$holds(() => $matches((input as any)["candidate"], "^[a-z][a-z0-9-]{1,31}$"))) {
          failures.push({ definition: "check_namespace", rule: "is_a_urn_namespace", path: '', failure_message: "The text is not a URN namespace" });
          ok = false;
        }
        if (!$holds(() => $eq((value as any)["candidate"], (input as any)["candidate"]))) {
          failures.push({ definition: "check_namespace", rule: "names_the_candidate", path: '', failure_message: "The answer does not name the text that was checked" });
          ok = false;
        }
        break;
      case "namespace_refused":
        if (!$holds(() => (!$matches((input as any)["candidate"], "^[a-z][a-z0-9-]{1,31}$")))) {
          failures.push({ definition: "check_namespace", rule: "is_not_a_urn_namespace", path: '', failure_message: "The text is a URN namespace" });
          ok = false;
        }
        if (!$holds(() => $eq((value as any)["candidate"], (input as any)["candidate"]))) {
          failures.push({ definition: "check_namespace", rule: "names_the_candidate", path: '', failure_message: "The answer does not name the text that was checked" });
          ok = false;
        }
        break;
    }
    return ok;
  },
  judge_weaker_contract: (input, output, value, failures) => {
    let ok = true;
    switch (output) {
      case "breaking_allowed":
        if (!$holds(() => !$eq((input as any)["from_version"], (input as any)["to_version"]))) {
          failures.push({ definition: "judge_weaker_contract", rule: "the_version_changed", path: '', failure_message: "A weaker contract with the same version is allowed" });
          ok = false;
        }
        break;
      case "breaking_refused":
        if (!$holds(() => ($eq((input as any)["from_version"], (input as any)["to_version"]) || ((!$matches((input as any)["to_version"], "^0\\.")) && (!$matches((input as any)["to_version"], "^[0-9]+\\.[0-9]+\\.[0-9]+-")))))) {
          failures.push({ definition: "judge_weaker_contract", rule: "keeps_the_version_or_a_stable_major", path: '', failure_message: "A weaker contract is refused, but its version changed to a 0.x version or a pre-release" });
          ok = false;
        }
        break;
    }
    return ok;
  },
  judge_bound_change: (input, output, value, failures) => {
    let ok = true;
    switch (output) {
      case "bound_judged":
        if (!$holds(() => (($eq((input as any)["old_bound"], (input as any)["new_bound"]) && $eq((value as any)["direction"], "same")) || (!$eq((input as any)["old_bound"], (input as any)["new_bound"]) && $eq($eq((value as any)["direction"], "narrower"), $eq($in((input as any)["bound_rule"], ["minimum", "exclusiveMinimum", "minLength", "minItems"]), (((input as any)["new_bound"] as any) > ((input as any)["old_bound"] as any)))))))) {
          failures.push({ definition: "judge_bound_change", rule: "direction_by_the_form", path: '', failure_message: "The direction of the new bound is wrong for the form of the rule" });
          ok = false;
        }
        break;
    }
    return ok;
  },
};

/**
 * The result of a call: the answer, or the rules that the input or the answer breaks. InputRejected:
 * the caller sent an input that breaks the contract. ContractViolation: the core answered what the
 * contract does not allow, which is a bug in the core.
 */
export type OperationResult<N extends OperationName = OperationName> =
  | ({ readonly ok: true; readonly domain: typeof DOMAIN; readonly operation: N } & ReturnType<DomainCore[N]>)
  | { readonly ok: false; readonly domain: typeof DOMAIN; readonly operation: N; readonly kind: 'InputRejected' | 'ContractViolation'; readonly failures: readonly Failure[] };

/** Runs an operation through the harness: checks the input, calls the core, then checks the answer and the rules. */
export function runOperation<N extends OperationName>(core: DomainCore, operation: N, input: unknown): OperationResult<N> {
  const contract = Operations[operation];
  const failures: Failure[] = [];
  if (!CHECKS[contract.input](input, '', failures)) return { ok: false, domain: DOMAIN, operation, kind: 'InputRejected', failures };
  const answered: unknown = (core[operation] as (input: unknown) => unknown)(input);
  const outputs: readonly string[] = contract.outputs;
  if (!$isObject(answered) || typeof answered['output'] !== 'string' || !outputs.includes(answered['output'])) {
    const message = `Must answer one of the outputs of ${operation}: ${outputs.join(', ')}`;
    return { ok: false, domain: DOMAIN, operation, kind: 'ContractViolation', failures: [{ definition: operation, rule: 'output', path: '', failure_message: message }] };
  }
  const output = answered['output'] as DefinitionName;
  if (!CHECKS[output](answered['value'], 'output', failures) || !OPERATION_RULES[operation](input, output, answered['value'], failures)) {
    return { ok: false, domain: DOMAIN, operation, kind: 'ContractViolation', failures };
  }
  return { ok: true, domain: DOMAIN, operation, output, value: answered['value'] } as OperationResult<N>;
}
